   [190]={next_id=191, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而回到现实的你，抱着极为虚弱的身体，凭借顽强的意志撑到现在，也终于抓到了天兆之星防御的破绽。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_13_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [191]={next_id=192, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所有人！集火它的伤口！！", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_13_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [192]={next_id=193, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="艾丽西亚的紫色剑气率先破空而至，红叶的枫火如长鞭般卷向同一处，朝晖与辉月的光刃交织成网，魁霎的巨像更是抡起拳头，带着千钧之力砸向天兆之星的躯体！", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_13_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
