   [194]={next_id=195, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="天兆之星发出凄厉的惨叫，目光死死锁定泽菲琳，声音里充满了不甘与怨毒。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_13_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7189", 0, 0, 11, 187.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [195]={next_id=196, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为什么？！你明明已经被我夺走碎片，明明该像你的母亲和教皇一样走向我设好的结局！！", msg_color="", msg_size=0, talker="天兆之星", audio="", img="arts/ui/bg/story/storybg_13_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7189", 0, 0, 11, 187.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
